const configMemoryEvaluationFiles={"config_snapshots.py": "\"\"\"Real POSIX path replacement, startup environment and validated application snapshots.\"\"\"\nfrom dataclasses import asdict, dataclass\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\n\n\n@dataclass(frozen=True)\nclass Config:\n    version: int\n    pool: int\n    timeout_ms: int\n\n\ndef swap_link(root, version):\n    pending = root / \"next\"\n    if pending.is_symlink():\n        pending.unlink()\n    pending.symlink_to(root / version, target_is_directory=True)\n    os.replace(str(pending), str(root / \"current\"))\n\n\ndef read_candidate(path, active):\n    value = json.loads(path.read_text())\n    if type(value) is not dict or set(value) != {\"version\", \"pool\", \"timeout_ms\"}:\n        raise ValueError(\"fields\")\n    if any(type(value[key]) is not int for key in value):\n        raise ValueError(\"integer_types\")\n    candidate = Config(**value)\n    if candidate.version <= active.version:\n        raise ValueError(\"stale_generation\")\n    if not 1 <= candidate.pool <= 12 or not 1 <= candidate.timeout_ms <= 500:\n        raise ValueError(\"range\")\n    if 4 * candidate.pool > 32:\n        raise ValueError(\"global_connection_budget\")\n    return candidate\n\n\ndef environment_probe():\n    child_code = (\"import os,sys; print(os.environ['LAB_POOL_LIMIT'],flush=True); \"\n                  \"sys.stdin.readline(); print(os.environ['LAB_POOL_LIMIT'],flush=True)\")\n    child_env = os.environ.copy()\n    child_env[\"LAB_POOL_LIMIT\"] = \"4\"\n    child = subprocess.Popen([sys.executable, \"-c\", child_code], env=child_env,\n                             stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n                             stderr=subprocess.PIPE, text=True)\n    before = child.stdout.readline().strip()\n    child_env[\"LAB_POOL_LIMIT\"] = \"6\"\n    rest, error = child.communicate(\"continue\\n\", timeout=5)\n    if child.returncode:\n        raise RuntimeError(error)\n    fresh = subprocess.check_output(\n        [sys.executable, \"-c\", \"import os; print(os.environ['LAB_POOL_LIMIT'])\"],\n        env=child_env, text=True, timeout=5).strip()\n    assert [before, rest.strip(), fresh] == [\"4\", \"4\", \"6\"]\n    return {\"running_before\": before, \"running_after_parent_template_change\": rest.strip(),\n            \"new_child\": fresh}\n\n\ndef main():\n    if os.name != \"posix\":\n        raise RuntimeError(\"This path/symlink fixture requires a POSIX filesystem (Linux/macOS).\")\n    old = Config(1, 4, 100)\n    new = Config(2, 6, 50)\n    with tempfile.TemporaryDirectory(prefix=\"infra-config-\") as temporary:\n        root = Path(temporary)\n        for name, config in [(\"v1\", old), (\"v2\", new)]:\n            folder = root / name\n            folder.mkdir()\n            (folder / \"pool\").write_text(str(config.pool))\n            (folder / \"timeout_ms\").write_text(str(config.timeout_ms))\n            (folder / \"config.json\").write_text(json.dumps(asdict(config)))\n        swap_link(root, \"v1\")\n        pool = int((root / \"current/pool\").read_text())\n        swap_link(root, \"v2\")\n        timeout = int((root / \"current/timeout_ms\").read_text())\n        mixed = {\"pool\": pool, \"timeout_ms\": timeout}\n        assert mixed == {\"pool\": 4, \"timeout_ms\": 50}\n        assert mixed not in [{\"pool\": 4, \"timeout_ms\": 100}, {\"pool\": 6, \"timeout_ms\": 50}]\n\n        swap_link(root, \"v1\")\n        with (root / \"current/config.json\").open() as held:\n            swap_link(root, \"v2\")\n            old_fd = json.load(held)\n        new_path = json.loads((root / \"current/config.json\").read_text())\n        assert old_fd == asdict(old) and new_path == asdict(new)\n\n        active = old\n        in_flight = active\n        active = read_candidate(root / \"current/config.json\", active)\n        assert active == new and in_flight == old\n        candidate_file = root / \"candidate.json\"\n        rejected = []\n        bad_candidates = [\n            (\"missing_field\", json.dumps({\"version\": 3, \"pool\": 6})),\n            (\"bool_pool\", json.dumps({\"version\": 4, \"pool\": True, \"timeout_ms\": 50})),\n            (\"global_budget\", json.dumps({\"version\": 5, \"pool\": 9, \"timeout_ms\": 50})),\n            (\"invalid_json\", \"{\"),\n            (\"old_generation\", json.dumps(asdict(old))),\n        ]\n        for name, body in bad_candidates:\n            candidate_file.write_text(body)\n            try:\n                proposed = read_candidate(candidate_file, active)\n            except (ValueError, json.JSONDecodeError) as error:\n                rejected.append({\"case\": name, \"kept_version\": active.version,\n                                 \"reason\": \"invalid_json\" if isinstance(error, json.JSONDecodeError) else str(error)})\n            else:\n                active = proposed\n                raise AssertionError(\"invalid candidate accepted\")\n        candidate_file.write_text(json.dumps({\"version\": 7, \"pool\": 4, \"timeout_ms\": 100}))\n        active = read_candidate(candidate_file, active)\n        assert active == Config(7, 4, 100)\n    print(json.dumps({\"mixed_separate_reads\": mixed, \"mixed_was_published\": False,\n                      \"held_descriptor_after_path_switch\": old_fd, \"new_path\": new_path,\n                      \"in_flight_snapshot\": asdict(in_flight), \"new_request_snapshot\": asdict(new),\n                      \"rejected_candidates\": rejected, \"rollback_values_new_generation\": asdict(active),\n                      \"environment\": environment_probe(),\n                      \"scope\": \"actual_local_files_and_processes_not_kubernetes_projection_or_watch_events\",\n                      \"retention_note\": \"Both fixture version directories remain present; no claim about old-volume garbage collection.\"},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "credential_rotation.py": "\"\"\"Real loopback HTTP rotation; fixture keys and independent in-memory sessions, not production auth.\"\"\"\nimport json\nimport secrets\nimport threading\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\nfrom urllib.error import HTTPError\nfrom urllib.request import Request, ProxyHandler, build_opener\n\nKEYS = {\"v1\": \"lab-only-fixture-A\", \"v2\": \"lab-only-fixture-B\", \"bad\": \"lab-only-invalid\"}\n\n\nclass Service:\n    def __init__(self):\n        self.accepted = {\"v1\"}\n        self.sessions = {}\n        self.events = []\n        self.lock = threading.Lock()\n\n    def accept(self, *versions):\n        with self.lock:\n            self.accepted = set(versions)\n\n    def revoke_session(self, token):\n        with self.lock:\n            self.sessions.pop(token, None)\n\n\ndef scenario(early_revoke=False):\n    service = Service()\n\n    class Handler(BaseHTTPRequestHandler):\n        def log_message(self, *args):\n            pass\n\n        def do_GET(self):\n            self.respond(False)\n\n        def do_POST(self):\n            length = int(self.headers.get(\"Content-Length\", \"0\"))\n            self.rfile.read(length)\n            self.respond(True)\n\n        def respond(self, create_session):\n            authorization = self.headers.get(\"Authorization\", \"\")\n            version = next((name for name, key in KEYS.items()\n                            if authorization == \"LabKey \" + key), None)\n            token = authorization[len(\"LabSession \"):] if authorization.startswith(\"LabSession \") else None\n            with service.lock:\n                if create_session:\n                    valid = self.path == \"/session\" and version in service.accepted\n                else:\n                    valid = self.path == \"/data\" and (version in service.accepted or token in service.sessions)\n                if valid and create_session:\n                    new_token = secrets.token_urlsafe(16)\n                    service.sessions[new_token] = version\n                    body = {\"session\": new_token}\n                elif valid:\n                    body = {\"total\": 37, \"authenticated_as\": version or service.sessions[token]}\n                else:\n                    body = {\"error\": \"not_authenticated\"}\n                status = 200 if valid else 401\n                service.events.append({\"path\": self.path, \"mode\": \"session\" if token else \"key\",\n                                       \"credential_version\": version or \"not_supplied\", \"status\": status})\n            payload = json.dumps(body).encode()\n            self.send_response(status)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(payload)))\n            self.end_headers()\n            self.wfile.write(payload)\n\n    server = HTTPServer((\"127.0.0.1\", 0), Handler)\n    thread = threading.Thread(target=server.serve_forever, kwargs={\"poll_interval\": 0.01})\n    thread.start()\n    opener = build_opener(ProxyHandler({}))\n    base = \"http://127.0.0.1:\" + str(server.server_port)\n\n    def request(version=None, session=None, create=False):\n        header = \"LabSession \" + session if session else \"LabKey \" + KEYS[version]\n        req = Request(base + (\"/session\" if create else \"/data\"),\n                      b\"{}\" if create else None,\n                      {\"Authorization\": header, \"Content-Type\": \"application/json\"})\n        try:\n            with opener.open(req, timeout=3) as response:\n                return response.status, json.load(response)\n        except HTTPError as error:\n            return error.code, json.load(error)\n\n    active = \"v1\"\n\n    def reload(candidate):\n        nonlocal active\n        status, _ = request(version=candidate)\n        if status == 200:\n            active = candidate\n            return True\n        return False\n\n    try:\n        initial, _ = request(version=active)\n        assert initial == 200\n        if early_revoke:\n            service.accept(\"v2\")\n            before = active\n            interrupted, _ = request(version=active)\n            assert interrupted == 401 and reload(\"v2\")\n            recovered, _ = request(version=active)\n            assert recovered == 200\n            return {\"client_before_reload\": before, \"server_accepts\": [\"v2\"],\n                    \"status_before_reload\": interrupted, \"client_after_reload\": active,\n                    \"status_after_reload\": recovered, \"events\": service.events}\n\n        _, login = request(version=\"v1\", create=True)\n        session = login[\"session\"]\n        service.accept(\"v1\", \"v2\")\n        new_probe, _ = request(version=\"v2\")\n        desired = \"v2\"\n        cached_status, _ = request(version=active)\n        cached = active\n        assert cached_status == new_probe == 200 and cached == \"v1\"\n        assert reload(desired)\n        assert not reload(\"bad\") and active == \"v2\"\n        service.accept(\"v2\")\n        old_key_status, _ = request(version=\"v1\")\n        new_key_status, _ = request(version=active)\n        old_session_status, _ = request(session=session)\n        service.revoke_session(session)\n        revoked_session_status, _ = request(session=session)\n        assert [old_key_status, new_key_status, old_session_status, revoked_session_status] == [401, 200, 200, 401]\n        return {\"new_credential_probe\": new_probe, \"desired_version_before_reload\": desired,\n                \"cached_client_before_reload\": cached, \"cached_request_status\": cached_status,\n                \"active_after_reload\": active, \"invalid_candidate_kept\": active,\n                \"old_key_after_revoke\": old_key_status, \"new_key_after_revoke\": new_key_status,\n                \"preexisting_session_after_key_revoke\": old_session_status,\n                \"session_after_explicit_revoke\": revoked_session_status,\n                \"events\": service.events}\n    finally:\n        server.shutdown()\n        server.server_close()\n        thread.join(timeout=5)\n        assert not thread.is_alive()\n\n\nif __name__ == \"__main__\":\n    result = {\"normal_overlap\": scenario(), \"early_revoke_counterexample\": scenario(True),\n              \"scope\": \"actual_local_http_fixture_keys_and_sessions_not_kubernetes_or_real_identity_provider\",\n              \"session_contract\": \"This fixture checks sessions independently; real providers may use different revocation semantics.\"}\n    print(json.dumps(result, ensure_ascii=False, indent=2))\n\n", "tensor_state_bytes.py": "\"\"\"Actual CPU parameter, gradient and lazy AdamW state payloads; not a GPU allocator measurement.\"\"\"\nfrom contextlib import nullcontext\nimport json\n\nimport torch\nfrom torch import nn\n\n\ndef payload(tensors):\n    items = list(tensors)\n    return {\"elements\": sum(t.numel() for t in items),\n            \"bytes\": sum(t.numel() * t.element_size() for t in items),\n            \"dtypes\": sorted({str(t.dtype) for t in items})}\n\n\ndef inventory(model, optimizer):\n    parameters = payload(model.parameters())\n    gradients = payload(p.grad for p in model.parameters() if p.grad is not None)\n    moments, steps, keys = [], [], set()\n    for state in optimizer.state.values():\n        keys.update(state)\n        for name, value in state.items():\n            if torch.is_tensor(value):\n                (steps if name == \"step\" else moments).append(value)\n    result = {\"parameters\": parameters, \"gradients\": gradients,\n              \"moments\": payload(moments), \"step_scalars\": payload(steps),\n              \"optimizer_state_keys\": sorted(keys)}\n    result[\"total_retained_payload_bytes\"] = sum(result[k][\"bytes\"] for k in\n                                                [\"parameters\", \"gradients\", \"moments\", \"step_scalars\"])\n    return result\n\n\ndef run(mode):\n    torch.manual_seed(17)\n    model = nn.Sequential(nn.Linear(4, 8), nn.ReLU(), nn.Linear(8, 2))\n    if mode == \"bf16_parameters\":\n        model = model.to(dtype=torch.bfloat16)\n    dtype = next(model.parameters()).dtype\n    optimizer = torch.optim.AdamW(model.parameters(), lr=0.001, foreach=False)\n    x = torch.randn(5, 4).to(dtype=dtype)\n    target = torch.randn(5, 2)\n    stages = {\"created\": inventory(model, optimizer)}\n    forward_dtype = None\n    for number in [1, 2]:\n        context = torch.autocast(\"cpu\", dtype=torch.bfloat16) if mode == \"fp32_autocast_bf16\" else nullcontext()\n        with context:\n            prediction = model(x)\n            forward_dtype = str(prediction.dtype)\n            loss = (prediction.float() - target).square().mean()\n        assert torch.isfinite(loss)\n        loss.backward()\n        if number == 1:\n            stages[\"after_backward\"] = inventory(model, optimizer)\n        optimizer.step()\n        stages[\"after_first_step\" if number == 1 else \"after_second_step\"] = inventory(model, optimizer)\n        optimizer.zero_grad(set_to_none=True)\n        if number == 1:\n            stages[\"after_zero_grad_none\"] = inventory(model, optimizer)\n    p = sum(t.numel() for t in model.parameters())\n    tensors = len(list(model.parameters()))\n    size = next(model.parameters()).element_size()\n    expected = 4 * p * size + 4 * tensors\n    assert p == 58 and tensors == 4\n    assert stages[\"created\"][\"moments\"][\"bytes\"] == 0\n    assert stages[\"after_backward\"][\"moments\"][\"bytes\"] == 0\n    assert stages[\"after_first_step\"][\"total_retained_payload_bytes\"] == expected\n    assert stages[\"after_second_step\"][\"total_retained_payload_bytes\"] == expected\n    assert stages[\"after_zero_grad_none\"][\"gradients\"][\"bytes\"] == 0\n    assert stages[\"after_first_step\"][\"optimizer_state_keys\"] == [\"exp_avg\", \"exp_avg_sq\", \"step\"]\n    return {\"mode\": mode, \"parameters\": p, \"parameter_tensors\": tensors,\n            \"forward_output_dtype\": forward_dtype, \"stages\": stages}\n\n\ndef main():\n    torch.set_num_threads(1)\n    modes = {mode: run(mode) for mode in [\"fp32\", \"fp32_autocast_bf16\", \"bf16_parameters\"]}\n    assert modes[\"fp32_autocast_bf16\"][\"forward_output_dtype\"] == \"torch.bfloat16\"\n    for key in [\"fp32\", \"fp32_autocast_bf16\"]:\n        assert modes[key][\"stages\"][\"after_first_step\"][\"total_retained_payload_bytes\"] == 944\n        assert modes[key][\"stages\"][\"after_first_step\"][\"parameters\"][\"dtypes\"] == [\"torch.float32\"]\n    assert modes[\"bf16_parameters\"][\"stages\"][\"after_first_step\"][\"total_retained_payload_bytes\"] == 480\n    base = torch.arange(8, dtype=torch.float32)\n    left, right = base[:6], base[2:]\n    storage = {t.untyped_storage().data_ptr(): t.untyped_storage().nbytes() for t in [left, right]}\n    alias = {\"view_element_bytes_sum\": sum(t.numel() * t.element_size() for t in [left, right]),\n             \"unique_underlying_storage_payload_bytes\": sum(storage.values()),\n             \"same_storage\": left.untyped_storage().data_ptr() == right.untyped_storage().data_ptr()}\n    assert alias == {\"view_element_bytes_sum\": 48, \"unique_underlying_storage_payload_bytes\": 32,\n                     \"same_storage\": True}\n    print(json.dumps({\"torch\": torch.__version__, \"device\": \"cpu\", \"modes\": modes, \"alias_example\": alias,\n                      \"scope\": \"actual_retained_tensor_payloads_not_cuda_peak_reserved_rss_or_training_quality\",\n                      \"note\": \"The direct BF16-parameter case illustrates state dtype; it is not a stability recommendation.\"},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "checkpoint_saved_tensors.py": "\"\"\"Actual saved-tensor payload reference and non-reentrant recomputation on CPU.\"\"\"\nimport copy\nimport json\n\nimport torch\nfrom torch import nn\nfrom torch.autograd.graph import saved_tensors_hooks\nfrom torch.utils.checkpoint import checkpoint\n\n\nclass Block(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.first = nn.Linear(32, 64)\n        self.second = nn.Linear(64, 32)\n        self.calls = 0\n\n    def forward(self, value):\n        self.calls += 1\n        return self.second(torch.nn.functional.gelu(self.first(value)))\n\n\ndef run(model, source, recompute):\n    parameter_storages = {p.untyped_storage().data_ptr() for p in model.parameters()}\n    storage_names, records = {}, []\n\n    def pack(tensor):\n        storage = tensor.untyped_storage()\n        pointer = storage.data_ptr()\n        name = storage_names.setdefault(pointer, \"storage-\" + str(len(storage_names)))\n        records.append({\"storage_id\": name, \"shape\": list(tensor.shape), \"dtype\": str(tensor.dtype),\n                        \"storage_bytes\": storage.nbytes(), \"parameter_storage\": pointer in parameter_storages})\n        # Share payload without retaining the input Tensor's autograd graph in the packed object.\n        return tensor.detach()\n\n    def unpack(tensor):\n        return tensor\n\n    inputs = source.detach().clone().requires_grad_(True)\n    with saved_tensors_hooks(pack, unpack):\n        value = inputs\n        for block in model:\n            value = checkpoint(block, value, use_reentrant=False) if recompute else block(value)\n        loss = value.square().mean()\n    # Metadata only: do not keep extra tensor references in the observation list.\n    before_backward = list(records)\n    unique_non_parameter = {row[\"storage_id\"]: row[\"storage_bytes\"] for row in before_backward\n                            if not row[\"parameter_storage\"] and row[\"storage_bytes\"] > 0}\n    calls_before = [block.calls for block in model]\n    loss.backward()\n    gradients = torch.cat([p.grad.reshape(-1) for p in model.parameters()] + [inputs.grad.reshape(-1)])\n    report = {\"forward_calls\": calls_before, \"total_calls_after_backward\": [b.calls for b in model],\n              \"saved_records_at_forward_end\": before_backward,\n              \"unique_non_parameter_saved_storage_bytes\": sum(unique_non_parameter.values()),\n              \"unique_non_parameter_saved_storages\": len(unique_non_parameter),\n              \"loss\": loss.item()}\n    return report, value.detach().clone(), gradients\n\n\ndef main():\n    torch.set_num_threads(1)\n    torch.manual_seed(29)\n    plain = nn.Sequential(Block(), Block(), Block())\n    recomputed = copy.deepcopy(plain)\n    source = torch.randn(16, 32)\n    normal, output, gradient = run(plain, source, False)\n    saved, new_output, new_gradient = run(recomputed, source, True)\n    output_error = (output - new_output).abs().max().item()\n    gradient_error = (gradient - new_gradient).abs().max().item()\n    assert output_error < 1e-6 and gradient_error < 1e-6\n    assert normal[\"forward_calls\"] == saved[\"forward_calls\"] == [1, 1, 1]\n    assert normal[\"total_calls_after_backward\"] == [1, 1, 1]\n    assert saved[\"total_calls_after_backward\"] == [2, 2, 2]\n    assert saved[\"unique_non_parameter_saved_storage_bytes\"] < normal[\"unique_non_parameter_saved_storage_bytes\"]\n    print(json.dumps({\"torch\": torch.__version__, \"device\": \"cpu\", \"dtype\": \"float32\",\n                      \"input_shape\": [16, 32], \"checkpoint_use_reentrant\": False,\n                      \"normal\": normal, \"checkpointed\": saved,\n                      \"output_max_abs_error\": output_error, \"gradient_max_abs_error\": gradient_error,\n                      \"scope\": \"saved_for_backward_storage_reference_not_peak_memory_rss_or_gpu_measurement\",\n                      \"limits\": [\"parameter storages excluded; views deduplicated by underlying storage\",\n                                 \"storage payload is not allocator reserved memory\",\n                                 \"fixed deterministic blocks without dropout; no random-state compatibility claim\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "evaluation_statistics.py": "\"\"\"Independent statistical examples from declared fixtures; no model benchmark or task execution.\"\"\"\nimport csv\nfrom fractions import Fraction\nimport json\nimport math\nfrom pathlib import Path\n\nZ95 = 1.959963984540054\n\n\ndef wilson(successes, total):\n    if total <= 0 or not 0 <= successes <= total:\n        raise ValueError(\"nonempty valid binomial counts required\")\n    p = successes / total\n    denominator = 1 + Z95 * Z95 / total\n    center = (p + Z95 * Z95 / (2 * total)) / denominator\n    half = Z95 * math.sqrt(p * (1 - p) / total + Z95 * Z95 / (4 * total * total)) / denominator\n    return {\"successes\": successes, \"total\": total, \"observed\": p,\n            \"lower\": max(0, center - half), \"upper\": min(1, center + half)}\n\n\ndef binary_scores(gold, predicted):\n    if len(gold) != len(predicted) or not gold:\n        raise ValueError(\"matching nonempty binary labels required\")\n    if any(type(x) is not int or x not in [0, 1] for x in gold + predicted):\n        raise ValueError(\"only integer binary labels accepted\")\n    tp = sum(g == p == 1 for g, p in zip(gold, predicted))\n    tn = sum(g == p == 0 for g, p in zip(gold, predicted))\n    fp = sum(g == 0 and p == 1 for g, p in zip(gold, predicted))\n    fn = sum(g == 1 and p == 0 for g, p in zip(gold, predicted))\n    positive = tp + fn\n    negative = tn + fp\n    safe_divide = lambda numerator, denominator: numerator / denominator if denominator else None\n    recalls = [v for v in [safe_divide(tp, positive), safe_divide(tn, negative)] if v is not None]\n    return {\"tp\": tp, \"tn\": tn, \"fp\": fp, \"fn\": fn,\n            \"accuracy\": (tp + tn) / len(gold),\n            \"positive_recall\": safe_divide(tp, positive), \"negative_recall\": safe_divide(tn, negative),\n            \"macro_recall_over_present_classes\": sum(recalls) / len(recalls),\n            \"positive_precision\": safe_divide(tp, tp + fp)}\n\n\ndef paired(path):\n    with path.open(newline=\"\") as handle:\n        rows = list(csv.DictReader(handle))\n    ids = [row[\"case_id\"] for row in rows]\n    if len(set(ids)) != len(ids):\n        raise ValueError(\"duplicate paired case identity\")\n    a, b = [], []\n    for row in rows:\n        if row[\"a_pass\"] not in {\"0\", \"1\"} or row[\"b_pass\"] not in {\"0\", \"1\"}:\n            raise ValueError(\"paired outcomes must be binary\")\n        a.append(int(row[\"a_pass\"]))\n        b.append(int(row[\"b_pass\"]))\n    if not rows:\n        raise ValueError(\"no paired cases\")\n    cells = {\"both_pass\": sum(x == y == 1 for x, y in zip(a, b)),\n             \"a_only\": sum(x == 1 and y == 0 for x, y in zip(a, b)),\n             \"b_only\": sum(x == 0 and y == 1 for x, y in zip(a, b)),\n             \"both_fail\": sum(x == y == 0 for x, y in zip(a, b))}\n    discordant = cells[\"a_only\"] + cells[\"b_only\"]\n    smaller = min(cells[\"a_only\"], cells[\"b_only\"])\n    exact = min(Fraction(1), 2 * sum((Fraction(math.comb(discordant, k), 2 ** discordant)\n                                     for k in range(smaller + 1)), Fraction(0)))\n    return {\"cases\": len(rows), \"cells\": cells, \"a\": wilson(sum(a), len(a)), \"b\": wilson(sum(b), len(b)),\n            \"b_minus_a_percentage_points\": 100 * (sum(b) - sum(a)) / len(rows),\n            \"discordant\": discordant, \"paired_two_sided_exact_p\": float(exact),\n            \"exact_fraction\": str(exact), \"case_ids_unique\": True}\n\n\ndef main():\n    # 1 = should complete, 0 = should refuse; these are declared synthetic labels.\n    gold = [1] * 5 + [0] * 20\n    reject_all = binary_scores(gold, [0] * 25)\n    assert reject_all[\"accuracy\"] == 0.8\n    assert reject_all[\"positive_recall\"] == 0 and reject_all[\"negative_recall\"] == 1\n    assert reject_all[\"macro_recall_over_present_classes\"] == 0.5\n    assert reject_all[\"positive_precision\"] is None\n    # Separate artifact-judge calibration example: 6 gold-valid, 6 gold-invalid.\n    judge = binary_scores([1] * 6 + [0] * 6, [1] * 5 + [0] + [1] * 2 + [0] * 4)\n    assert (judge[\"tp\"], judge[\"fp\"], judge[\"fn\"], judge[\"tn\"]) == (5, 2, 1, 4)\n    assert judge[\"positive_precision\"] == 5 / 7\n    pairs = paired(Path(__file__).with_name(\"paired-example.csv\"))\n    assert pairs[\"cells\"] == {\"both_pass\": 16, \"a_only\": 2, \"b_only\": 4, \"both_fail\": 3}\n    assert pairs[\"a\"][\"successes\"] == 18 and pairs[\"b\"][\"successes\"] == 20\n    assert pairs[\"b_minus_a_percentage_points\"] == 8\n    assert pairs[\"paired_two_sided_exact_p\"] == 0.6875\n    intervals = {\"five_of_five\": wilson(5, 5), \"hundred_of_hundred\": wilson(100, 100)}\n    assert 0.56 < intervals[\"five_of_five\"][\"lower\"] < 0.57\n    assert 0.96 < intervals[\"hundred_of_hundred\"][\"lower\"] < 0.97\n    invalid_counts = False\n    try:\n        wilson(0, 0)\n    except ValueError:\n        invalid_counts = True\n    assert invalid_counts\n    print(json.dumps({\"fixture_type\": \"declared_synthetic_labels_and_paired_csv_not_agent_runs\",\n                      \"reject_all_imbalanced\": reject_all, \"artifact_judge_calibration\": judge,\n                      \"wilson_95_examples\": intervals, \"paired_comparison\": pairs,\n                      \"zero_task_interval_rejected\": invalid_counts,\n                      \"assumptions\": [\"Wilson example assumes independent binomial observations\",\n                                      \"paired exact test assumes independent case pairs and exchangeability under the null\",\n                                      \"fixed illustrative outcomes do not establish any real model success probability\",\n                                      \"large p is not proof of equality; overlapping marginal intervals are not a paired test\"]},\n                     ensure_ascii=False, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "paired-example.csv": "case_id,a_pass,b_pass\npair-01,1,1\npair-02,1,1\npair-03,1,1\npair-04,1,1\npair-05,1,1\npair-06,1,1\npair-07,1,1\npair-08,1,1\npair-09,1,1\npair-10,1,1\npair-11,1,1\npair-12,1,1\npair-13,1,1\npair-14,1,1\npair-15,1,1\npair-16,1,1\npair-17,1,0\npair-18,1,0\npair-19,0,1\npair-20,0,1\npair-21,0,1\npair-22,0,1\npair-23,0,0\npair-24,0,0\npair-25,0,0\n\n"};
