 const a=articles.find(a=>a.id==='training-storage');
 a.desc=a.intro='先按对象、文件、块接口分清数据责任，再计算请求粒度、带宽与读取放大。用本机 HTTP 对照整分片与范围读取，核对同一批样本。';
